// Made by this material's graph (the Material tab's Graph view): edit the graph,
// not this code, which is made again from it.
fn surface(input: SurfaceInput) -> Surface {
    let n2 = textureSample(base_color_texture, material_sampler, input.uv); // Texture Sample
    let n3 = textureSample(emissive_texture, material_sampler, input.uv); // Texture Sample
    let n5 = n3.rgb * srgb(parameter(0).xyz); // Multiply
    let n6 = graph_perlin_noise(input.uv * 4.0f); // Noise
    let n7 = smoothstep(0.4f, 0.6f, n6); // Smooth Step
    let n8 = mix(n2.rgb, n5, vec3<f32>(n7)); // Mix
    var out: Surface;
    out.base_color = n8;
    out.metalness = input.metalness;
    out.roughness = parameter(1).x;
    out.normal = input.normal;
    out.emissive = input.emissive;
    out.opacity = input.opacity;
    return out;
}

// A random number from 0 to 1 for each point (cell corner).
fn graph_hash(p: vec2<f32>) -> f32 {
    var q = fract(p * vec2<f32>(123.34, 456.21));
    q = q + dot(q, q + 45.32);
    return fract(q.x * q.y);
}

// Random slopes at cell corners (Perlin's gradient noise), 0 to 1.
fn graph_corner_slope(corner: vec2<f32>, offset: vec2<f32>) -> f32 {
    let angle = graph_hash(corner) * 6.2831853;
    return dot(vec2<f32>(cos(angle), sin(angle)), offset);
}

fn graph_perlin_noise(p: vec2<f32>) -> f32 {
    let i = floor(p);
    let f = fract(p);
    let u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
    let a = graph_corner_slope(i, f);
    let b = graph_corner_slope(i + vec2<f32>(1.0, 0.0), f - vec2<f32>(1.0, 0.0));
    let c = graph_corner_slope(i + vec2<f32>(0.0, 1.0), f - vec2<f32>(0.0, 1.0));
    let d = graph_corner_slope(i + vec2<f32>(1.0, 1.0), f - vec2<f32>(1.0, 1.0));
    return clamp(mix(mix(a, b, u.x), mix(c, d, u.x), u.y) * 0.7071 + 0.5, 0.0, 1.0);
}
